test("bundle failed Goal supplement stays gated and recovers without replay", async ({ h4 }) => {
  const { page } = h4;
  await h4.open("bundle");
  await assertFrontendRuntime(page, "bundle");
  await h4.submit(GOAL_V2_GATE_SETUP_USER);
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: GOAL_V2_GATE_REQUEST,
  })).toHaveCount(1);
  await expect(page.locator("#activeRunBanner.visible")).toHaveCount(0);
  const sessionId = await page.locator(
    "#sessionList .session-row.active button.session-main",
  ).getAttribute("data-session-id");
  const readState = () => readGoalAcceptanceState(page, sessionId);
  await expect.poll(readState).toMatchObject({
    projection: { revision: 8, goal: { gate: { type: "waiting_user" } } },
  });
  const waiting = await readState();
  const goalId = waiting.projection.goal.goalId;
  expect(waiting.projection.goal.steps.map((step) => step.status)).toEqual([
    "completed", "completed", "in_progress",
  ]);
  const setupRunId = h4.controlIds().agentRunIds[0];
  const metricsAtGate = await h4.metrics();
  expect(metricsAtGate.chatRequests).toHaveLength(9);
  expect(metricsAtGate.toolExecutions).toEqual([{ action: "read_file", path: "fixture.txt" }]);

  await restoreGoalH4Connection(h4);
  await h4.submit(GOAL_V2_GATE_FAILURE_USER);
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: GOAL_V2_GATE_FAILURE_ERROR,
  })).toHaveCount(1, { timeout: 60_000 });
  await expect(page.locator("#activeRunBanner.visible")).toHaveCount(0);
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(2);
  let snapshots = await readObservedAgentSnapshots(h4, page);
  const failedRun = snapshots.find((snapshot) => snapshot.status === "failed");
  expect(failedRun).toMatchObject({
    sessionId,
    runKind: "foreground",
    goalOperationsEnabled: true,
    errorCode: "upstream_error",
  });
  expect(String(failedRun.error || "")).toContain(GOAL_V2_GATE_FAILURE_ERROR);
  expect(failedRun.toolExecutions).toEqual([]);
  expect(countModelRounds(failedRun)).toBe(0);
  const afterFailure = await readState();
  expect(afterFailure.projection).toMatchObject({
    revision: 8,
    goal: { goalId, lifecycle: "active", gate: { type: "waiting_user" } },
  });
  expect(afterFailure.projection.goal.steps.map((step) => step.status)).toEqual([
    "completed", "completed", "in_progress",
  ]);
  const metricsAfterFailure = await h4.metrics();
  expect(metricsAfterFailure.chatRequests).toHaveLength(10);
  expect(metricsAfterFailure.toolExecutions).toEqual(metricsAtGate.toolExecutions);
  await expect(page.locator("#goalProgress")).toBeVisible();
  await expect(page.locator("#goalProgressCount")).toHaveText("3/3");
  await expect(page.locator("#messages .goal-completion-marker")).toHaveCount(0);

  const failureReloadBoundary = h4.requestBoundary();
  await h4.reloadRuntime("bundle");
  await restoreGoalH4Connection(h4);
  await expect(page.locator("#goalProgress")).toBeVisible();
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: GOAL_V2_GATE_FAILURE_ERROR,
  })).toHaveCount(1);
  expect(new Set(h4.controlIds().agentRunIds)).toEqual(new Set([setupRunId, failedRun.agentRunId]));
  expect((await h4.metrics()).chatRequests).toEqual(metricsAfterFailure.chatRequests);
  expect(h4.requestEvidenceSince(failureReloadBoundary).agentPost).toBe(0);

  const recoveryBoundary = h4.requestBoundary();
  await h4.submit(GOAL_V2_GATE_RETRY_USER);
  const recoveryFinal = page.locator("#messages article.msg.assistant").filter({
    hasText: GOAL_V2_GATE_FINAL,
  });
  await expect(recoveryFinal).toHaveCount(1);
  await expect(page.locator("#activeRunBanner.visible")).toHaveCount(0);
  await expect(page.locator("#goalProgress")).toBeHidden();
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(3);
  snapshots = await readObservedAgentSnapshots(h4, page);
  const recoveredRun = snapshots.find((snapshot) => (
    snapshot.agentRunId !== setupRunId && snapshot.agentRunId !== failedRun.agentRunId
  ));
  expect(recoveredRun).toMatchObject({
    status: "completed",
    sessionId,
    runKind: "foreground",
    goalOperationsEnabled: true,
    permissionProfile: failedRun.permissionProfile,
  });
  expect(recoveredRun.toolExecutions).toEqual([]);
  expect(countModelRounds(recoveredRun)).toBe(3);
  const recovered = await readState();
  expect(recovered.projection).toMatchObject({
    revision: 10,
    goal: { goalId, lifecycle: "completed", currentStepId: null, gate: null },
  });
  expect(recovered.projection.goal.steps.map((step) => step.status)).toEqual([
    "completed", "completed", "completed",
  ]);
  const metricsRecovered = await h4.metrics();
  expect(metricsRecovered.chatRequests).toHaveLength(13);
  expect(metricsRecovered.toolExecutions).toEqual(metricsAtGate.toolExecutions);
  expect(h4.requestEvidenceSince(recoveryBoundary).agentPost).toBe(1);
  expect(recovered.session.messages.filter((message) => (
    message.role === "user" && String(message.content || "").includes(GOAL_V2_GATE_FAILURE_USER)
  ))).toHaveLength(1);
  expect(recovered.session.messages.filter((message) => (
    message.role === "user" && String(message.content || "").includes(GOAL_V2_GATE_RETRY_USER)
  ))).toHaveLength(1);
  expect(recovered.session.messages.filter((message) => (
    message.meta?.goalOrigin?.confirmed === true
  ))).toHaveLength(1);
  await expect(page.locator("#messages article.tool-process")).toHaveCount(1);
  await expect(page.locator("#messages article.msg.assistant .response-info")).toHaveCount(2);
  await expect(page.locator("#messages .goal-completion-marker")).toHaveCount(1);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence("bundle-goal-v2-user-gate-failure-recovery", {
    sessionId,
    goalId: idHash(goalId),
    waitingRevision: waiting.projection.revision,
    failedRevision: afterFailure.projection.revision,
    recoveredRevision: recovered.projection.revision,
    agentRuns: snapshots.length,
    failedErrorCode: failedRun.errorCode,
    modelRequests: metricsRecovered.chatRequests.length,
    successfulTools: metricsRecovered.toolExecutions.length,
    replayedTools: 0,
  });
});

async function exerciseContextBudgetSnapshot(h4, runtime) {
  const { page } = h4;
  const softModel = CONTEXT_BUDGET_SOFT_MODEL_ID;
  const hardModel = CONTEXT_BUDGET_HARD_MODEL_ID;
  const agentBudgetRequests = [];
  await pinH4BaseUrlAcrossReloads(page, h4.host.ready.fakeUrl);
  await page.addInitScript(({ credential }) => {
    if (!/^https?:$/.test(location.protocol)) return;
    sessionStorage.setItem("h4-preserve-key-config", "1");
    if (sessionStorage.getItem("h4-context-budget-catalog-ready") === "1") return;
    localStorage.setItem("code-key-config", JSON.stringify([{
      name: "H4 context budget catalog",
      key: credential,
      enabled: true,
      source: "manual",
      connectionId: "manual_h4_context_budget_catalog",
    }]));
    localStorage.removeItem("code-model");
    localStorage.removeItem("code-model-route-ref");
    localStorage.removeItem("code-model-route-revision");
    sessionStorage.setItem("h4-context-budget-catalog-ready", "1");
  }, { credential: CONTEXT_BUDGET_CATALOG_KEY });
  const target = runtime === "classic"
    ? `${h4.host.ready.codeUrl}/dist/frontend/index.classic.html`
    : `${h4.host.ready.codeUrl}/`;
  await page.goto(target, { waitUntil: "domcontentloaded" });
  await assertFrontendRuntime(page, runtime);
  await expect.poll(async () => page.evaluate(async (models) => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const catalog = await response.json();
    const routes = (catalog.routes || []).filter((route) => models.includes(route.modelId));
    return {
      status: response.status,
      routeCount: routes.length,
      modelIds: routes.map((route) => route.modelId).sort(),
      allEnabled: routes.every((route) => route.enabled !== false),
      allCredentialed: routes.every((route) => route.credentialsAvailable === true),
      selectedModel: document.querySelector("#modelPillBtn")?.dataset.model || "",
    };
  }, [softModel, hardModel])).toEqual({
    status: 200,
    routeCount: 2,
    modelIds: [softModel, hardModel].sort(),
    allEnabled: true,
    allCredentialed: true,
    selectedModel: "",
  });
  page.on("request", (request) => {
    const url = new URL(request.url());
    if (request.method() !== "POST" || url.pathname !== "/api/agent/runs") return;
    const payload = request.postDataJSON();
    agentBudgetRequests.push({
      model: payload?.payload?.model || "",
      contextBudgetTokens: payload?.contextBudgetTokens ?? null,
    });
  });
  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).not.toHaveClass(/hidden/);
  await expect(page.locator("#settingsMaxTokens")).toHaveValue("auto");
  await expect(page.locator("#settingsContextBudget").locator("xpath=preceding-sibling::span")).toHaveText(
    "Maximum context window",
  );
  await page.locator("#settingsContextBudget").evaluate((element) => {
    element.value = "200K";
    element.dispatchEvent(new Event("change", { bubbles: true }));
  });
  await expect(page.locator("#settingsContextBudget")).toHaveValue("200k");
  await expect(page.locator("#settingsContextBudgetStatus")).toBeHidden();
  expect(await page.evaluate(() => localStorage.getItem("code-context-budget"))).toBe("200000");
  await page.locator("#settingsContextBudget").evaluate((element) => {
    element.value = "12g";
    element.dispatchEvent(new Event("change", { bubbles: true }));
  });
  await expect(page.locator("#settingsContextBudget")).toHaveValue("200k");
  await expect(page.locator("#settingsContextBudgetStatus")).toContainText("Invalid format");
  expect(await page.evaluate(() => localStorage.getItem("code-context-budget"))).toBe("200000");
  await page.locator("#closeSettingsPage").click();

  await page.locator("#settingsMenuBtn").click();
  await page.locator("#settingsRefreshModels").click();
  await expect(page.locator("#settingsModelList")).toContainText(softModel);
  await expect(page.locator("#settingsModelList")).toContainText(hardModel);
  await expect(page.locator("#settingsContextBudget")).toHaveValue("200k");
  await expect(page.locator("#settingsContextBudgetStatus")).toBeHidden();
  const routeIdentity = await page.evaluate(async (model) => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const catalog = await response.json();
    const route = (catalog.routes || []).find((item) => item.modelId === model);
    return {
      routeRef: String(route?.routeRef || ""),
      catalogRevision: Number(catalog.catalogRevision || 0),
      modelId: String(route?.modelId || ""),
    };
  }, hardModel);
  expect(routeIdentity).toMatchObject({
    routeRef: expect.stringMatching(/^mr1_[a-f0-9]{64}$/),
    catalogRevision: expect.any(Number),
    modelId: hardModel,
  });
  const normalizedResponse = await fetchRoutedModelCatalog(
    h4.host.ready.codeUrl,
    routeIdentity,
  );
  const normalizedCatalog = {
    status: normalizedResponse.status,
    data: normalizedResponse.body.data || [],
  };
  expect(normalizedCatalog.status).toBe(200);
  expect(normalizedCatalog.data.find((item) => item.id === softModel)).toMatchObject({
    contextWindowTokens: 400000,
    contextWindowSource: "official",
    contextWindowHard: false,
  });
  expect(normalizedCatalog.data.find((item) => item.id === hardModel)).toMatchObject({
    contextWindowTokens: 128000,
    contextWindowSource: "metadata",
    contextWindowHard: true,
  });
  await page.locator("#closeSettingsPage").click();
  await page.locator("#modelPillBtn").click();
  await page.locator(`#modelPillDropdown [data-model="${softModel}"]`).click();
  await expect(page.locator("#modelPillBtn")).toHaveAttribute("data-model", softModel);
  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsContextBudget")).toHaveValue("200k");
  await expect(page.locator("#settingsContextBudgetStatus")).toBeHidden();
  await page.locator("#closeSettingsPage").click();
  await page.locator("#modelPillBtn").click();
  await page.locator(`#modelPillDropdown [data-model="${hardModel}"]`).click();
  await expect(page.locator("#modelPillBtn")).toHaveAttribute("data-model", hardModel);
  await expect(page.locator("#contextBudget")).toHaveValue("200k");
  await expect(page.locator("#baseUrl")).toHaveValue(h4.host.ready.fakeUrl);
  expect(await page.evaluate((credential) => {
    const entries = JSON.parse(localStorage.getItem("code-key-config") || "[]");
    return entries.length === 1
      && entries[0]?.enabled !== false
      && entries[0]?.key === credential;
  }, CONTEXT_BUDGET_CATALOG_KEY)).toBe(true);
  await h4.submit("H4_PLAIN_USER");
  await expect(page.locator("#messages article.msg.assistant").filter({ hasText: "H4_PLAIN_FINAL" })).toHaveCount(1);
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(1);
  const agentRunId = h4.controlIds().agentRunIds[0];
  const snapshot = await fetchProductionJson(
    page,
    `/api/agent/runs/${encodeURIComponent(agentRunId)}?cursor=0&wait=0`,
  );
  expect(snapshot.status).toBe(200);
  expect(snapshot.body).toMatchObject({
    model: hardModel,
    contextLimit: 128000,
    contextWindowTokens: 128000,
    contextBudgetTokens: 200000,
    contextWindowSource: "metadata",
    contextWindowHard: true,
    budgetClamped: true,
    budgetAboveEstimate: false,
  });
  expect(agentBudgetRequests).toEqual([{
    model: hardModel,
    contextBudgetTokens: 200000,
  }]);

  const sessionButton = page.locator("#sessionList .session-row.active button.session-main");
  const sessionId = await sessionButton.getAttribute("data-session-id");
  expect(sessionId).toBeTruthy();
  const metricsBeforeReload = await h4.metrics();
  const reloadBoundary = h4.requestBoundary();
  await h4.reloadRuntime(runtime);
  await expect(page.locator("#maxTokens")).toHaveValue("auto");
  await expect(page.locator("#contextBudget")).toHaveValue("200k");
  expect(await page.evaluate(() => localStorage.getItem("code-context-budget"))).toBe("200000");
  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsContextBudget")).toHaveValue("200k");
  await expect(page.locator("#settingsContextBudgetStatus")).toBeHidden();
  await page.locator("#closeSettingsPage").click();
  await page.locator("#usageStrip").click();
  await expect(page.locator("#statContext")).toHaveText(/^\d+%$/);
  await expect(page.locator("#tokenContext")).toHaveText(/^\d+% · 128k$/);
  const persisted = await fetchProductionJson(
    page,
    `/api/sessions/${encodeURIComponent(sessionId)}`,
  );
  expect(persisted.status).toBe(200);
  expect(persisted.body?.stats?.contextResolution).toMatchObject({
    contextLimit: 128000,
    contextWindowTokens: 128000,
    contextBudgetTokens: 200000,
    contextWindowSource: "metadata",
    contextWindowHard: true,
    budgetClamped: true,
    budgetAboveEstimate: false,
  });
  const metricsAfterReload = await h4.metrics();
  expect(h4.requestEvidenceSince(reloadBoundary).agentPost).toBe(0);
  expect(metricsAfterReload.chatRequests).toEqual(metricsBeforeReload.chatRequests);
  expect(metricsAfterReload.toolExecutions).toEqual(metricsBeforeReload.toolExecutions);
  expect(metricsAfterReload.production.agentRuns).toEqual(metricsBeforeReload.production.agentRuns);
  expect(metricsAfterReload.modelRouteRequests.filter((entry) => (
    entry.kind === "catalog" && entry.keyGroup === "context-budget-catalog"
  )).length).toBeGreaterThanOrEqual(2);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-context-budget-snapshot`, {
    runtime,
    agentRunId: idHash(agentRunId),
    sessionId: idHash(sessionId),
    contextLimit: snapshot.body.contextLimit,
    desiredMaximum: snapshot.body.contextBudgetTokens,
    capability: snapshot.body.contextWindowTokens,
    source: snapshot.body.contextWindowSource,
    persistedAfterReload: true,
  });
}

test("bundle context budget freezes in AgentRun and survives reload", async ({ h4 }) => {
  await exerciseContextBudgetSnapshot(h4, "bundle");
});

test("direct classic context budget matches bundle and survives reload", async ({ h4 }) => {
  await exerciseContextBudgetSnapshot(h4, "classic");
});

async function exerciseContextCalibrationRecovery(h4, runtime) {
  const { page } = h4;
  await h4.open(runtime);
  await assertFrontendRuntime(page, runtime);
  await restoreGoalH4Connection(h4);
  await page.evaluate(({ secondaryKey }) => {
    const current = JSON.parse(localStorage.getItem("code-key-config") || "[]");
    localStorage.setItem("code-key-config", JSON.stringify([
      current[0],
      {
        name: "H4 unused calibration fallback",
        key: secondaryKey,
        enabled: true,
        source: "manual",
      },
    ].filter(Boolean)));
  }, { secondaryKey: CONTEXT_CALIBRATION_UNUSED_KEY });
  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).not.toHaveClass(/hidden/);
  await page.locator("#settingsRefreshModels").click();
  await expect(page.locator("#settingsModelList")).toContainText(MODEL_ID);
  await page.locator("#closeSettingsPage").click();
  await expect(page.locator("#modelPillBtn")).toHaveAttribute("data-model", MODEL_ID);

  await h4.submit("H4_PLAIN_USER");
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: "H4_PLAIN_FINAL",
  })).toHaveCount(1);
  const metricsBefore = await h4.metrics();

  await h4.submit(CONTEXT_CALIBRATION_USER);
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: CONTEXT_CALIBRATION_FINAL,
  })).toHaveCount(1);
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(2);
  const snapshots = await readObservedAgentSnapshots(h4, page);
  const calibrated = snapshots.find((snapshot) => snapshot.calibrationApplied === true);
  expect(calibrated).toMatchObject({
    status: "completed",
    runKind: "foreground",
    contextLimit: 64000,
    contextWindowTokens: 128000,
    contextWindowSource: "unknown",
    calibrationCapTokens: 64000,
    calibrationEvidenceKind: "explicit_max",
    calibrationApplied: true,
  });
  expect(calibrated.calibrationExpiresAt).toMatch(/Z$/);
  expect(calibrated.round).toBe(1);
  expect(calibrated.compactions).toHaveLength(1);
  expect(calibrated.compactions[0].reason).toBe("context_window_exceeded");

  const metricsAfter = await h4.metrics();
  const recoveryRequests = metricsAfter.chatRequests.slice(metricsBefore.chatRequests.length);
  expect(recoveryRequests.map((item) => item.scenario)).toEqual([
    "context-calibration",
    "context-compaction",
    "context-calibration",
  ]);
  expect(recoveryRequests.every((item) => !item.usedContextCalibrationUnusedKey)).toBe(true);
  const notice = page.locator("#toastContainer .toast.warning").filter({
    hasText: "smaller actual window",
  });
  await expect(notice).toHaveCount(1);
  expect(await page.evaluate(({ runId }) => (
    sessionStorage.getItem(`code-context-calibration-notice:${runId}:64000`)
  ), { runId: calibrated.agentRunId })).toBe("1");

  const sessionId = await page.locator(
    "#sessionList .session-row.active button.session-main",
  ).getAttribute("data-session-id");
  expect(sessionId).toBeTruthy();
  const persisted = await fetchProductionJson(
    page,
    `/api/sessions/${encodeURIComponent(sessionId)}`,
  );
  expect(persisted.status).toBe(200);
  expect(persisted.body?.stats?.contextResolution).toMatchObject({
    contextLimit: 64000,
    contextWindowTokens: 128000,
    calibrationCapTokens: 64000,
    calibrationEvidenceKind: "explicit_max",
    calibrationApplied: true,
  });
  expect(persisted.body.stats.contextResolution.sourceRunCreatedAt).toMatch(
    /\.\d{6}$/,
  );

  await h4.reloadRuntime(runtime);
  await page.locator("#usageStrip").click();
  await expect(page.locator("#tokenContext")).toHaveText(/^\d+% · 64k$/);
  await expect(page.locator("#toastContainer .toast.warning").filter({
    hasText: "smaller actual window",
  })).toHaveCount(0);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-context-calibration-recovery`, {
    runtime,
    agentRunId: idHash(calibrated.agentRunId),
    sessionId: idHash(sessionId),
    contextLimit: calibrated.contextLimit,
    evidenceKind: calibrated.calibrationEvidenceKind,
    recoveryRequests: recoveryRequests.length,
    unusedKeyRequests: recoveryRequests.filter(
      (item) => item.usedContextCalibrationUnusedKey,
    ).length,
    persistedAfterReload: true,
  });
}

test("bundle context calibration retries the failing key once and persists", async ({ h4 }) => {
  await exerciseContextCalibrationRecovery(h4, "bundle");
});

test("direct classic context calibration matches bundle and survives reload", async ({ h4 }) => {
  await exerciseContextCalibrationRecovery(h4, "classic");
});

async function exerciseOfficialCatalogSnapshot(h4, runtime) {
  const { page } = h4;
  await h4.open(runtime);
  await assertFrontendRuntime(page, runtime);
  let catalogRequests = 0;
  await page.route("**/proxy/models", async (route) => {
    catalogRequests += 1;
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify({
        data: [{
          id: "gpt-5.4-mini",
          contextWindowTokens: 400000,
          contextWindowSource: "official",
          contextWindowHard: false,
          maxOutputTokens: 128000,
          officialProvider: "openai",
          officialCatalogRevision: "2026-08-21.c1",
          metadataStatus: "missing",
        }],
      }),
    });
  });
  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).not.toHaveClass(/hidden/);
  const settingsRefresh = page.locator("#settingsRefreshModels");
  await expect(settingsRefresh).toBeVisible();
  await expect(settingsRefresh).toBeEnabled();
  await settingsRefresh.click();
  await expect(page.locator("#settingsModelList")).toContainText("gpt-5.4-mini");
  await expect(page.locator("#settingsModelCount")).toHaveText("1");
  expect(catalogRequests).toBeGreaterThanOrEqual(1);
  await page.locator("#closeSettingsPage").click();
  await expect(page.locator("#settingsPage")).toHaveClass(/hidden/);
  await expect(page.locator("#modelPillDropdown [data-model='gpt-5.4-mini']")).toHaveCount(1);
  await page.locator("#modelPillBtn").click();
  await page.locator("#modelPillDropdown [data-model='gpt-5.4-mini']").click();
  await expect(page.locator("#modelPillBtn")).toHaveAttribute("data-model", "gpt-5.4-mini");
  await expect(page.locator("#contextBudget")).toHaveValue("");
  await restoreGoalH4Connection(h4, "gpt-5.4-mini");

  await h4.submit("H4_PLAIN_USER");
  await expect(page.locator("#messages article.msg.assistant").filter({ hasText: "H4_PLAIN_FINAL" })).toHaveCount(1);
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(1);
  const agentRunId = h4.controlIds().agentRunIds[0];
  const snapshot = await fetchProductionJson(
    page,
    `/api/agent/runs/${encodeURIComponent(agentRunId)}?cursor=0&wait=0`,
  );
  expect(snapshot.status).toBe(200);
  expect(snapshot.body).toMatchObject({
    model: "gpt-5.4-mini",
    contextLimit: 400000,
    contextWindowTokens: 400000,
    contextBudgetTokens: null,
    contextWindowSource: "official",
    contextWindowHard: false,
    budgetClamped: false,
    budgetAboveEstimate: false,
  });

  const sessionButton = page.locator("#sessionList .session-row.active button.session-main");
  const sessionId = await sessionButton.getAttribute("data-session-id");
  expect(sessionId).toBeTruthy();
  const catalogRequestsBeforeReload = catalogRequests;
  const clientStateBeforeReload = await page.evaluate(() => {
    const cache = JSON.parse(localStorage.getItem("code-model-catalog-cache-v1") || "null");
    return {
      selectedModel: localStorage.getItem("code-model"),
      cachedModels: Array.isArray(cache?.models) ? cache.models : [],
    };
  });
  expect(clientStateBeforeReload).toEqual({
    selectedModel: "gpt-5.4-mini",
    cachedModels: ["gpt-5.4-mini"],
  });
  await h4.reloadRuntime(runtime);
  await expect.poll(() => catalogRequests).toBeGreaterThan(catalogRequestsBeforeReload);
  let clientStateAfterReload = null;
  await expect.poll(async () => {
    clientStateAfterReload = await page.evaluate(() => {
      const cache = JSON.parse(localStorage.getItem("code-model-catalog-cache-v1") || "null");
      return {
        selectedModel: localStorage.getItem("code-model"),
        cachedModels: Array.isArray(cache?.models) ? cache.models : [],
      };
    });
    return clientStateAfterReload;
  }).toEqual(clientStateBeforeReload);
  await expect(page.locator("#modelPillDropdown [data-model='gpt-5.4-mini']")).toHaveCount(1);
  await expect(page.locator("#modelPillBtn")).toHaveAttribute("data-model", "gpt-5.4-mini");
  await expect(page.locator("#messages article.msg.assistant").filter({ hasText: "H4_PLAIN_FINAL" })).toHaveCount(1);
  let persisted = null;
  await expect.poll(async () => {
    persisted = await fetchProductionJson(
      page,
      `/api/sessions/${encodeURIComponent(sessionId)}`,
    );
    return persisted.body?.stats?.contextResolution?.contextWindowSource || "";
  }).toBe("official");
  expect(persisted.body.stats.contextResolution).toMatchObject({
    contextLimit: 400000,
    contextWindowTokens: 400000,
    contextBudgetTokens: null,
    contextWindowSource: "official",
    contextWindowHard: false,
  });
  expect(catalogRequests).toBeGreaterThanOrEqual(2);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-official-context-catalog`, {
    runtime,
    model: "gpt-5.4-mini",
    contextLimit: snapshot.body.contextLimit,
    source: snapshot.body.contextWindowSource,
    hard: snapshot.body.contextWindowHard,
    catalogRequests,
    catalogRequestsBeforeReload,
    savedModelBeforeReload: clientStateBeforeReload.selectedModel,
    savedModelAfterReload: clientStateAfterReload.selectedModel,
    runtimeOfficialNetworkRequests: 0,
    persistedAfterReload: true,
  });
}

