async function exerciseKeyRouteRevocation(h4, runtime) {
  const { page } = h4;
  const removedRoute = await configureConnectionRouteCatalog(h4, runtime);
  const initialAgentRuns = h4.controlIds().agentRunIds.length;
  const initialMetrics = await h4.metrics();
  expect(initialMetrics.chatRequests).toHaveLength(0);

  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).toBeVisible();
  const removedRow = page.locator(
    '#settingsKeyList .key-row[data-connection-id="manual_h4_deepseek_connection"]',
  );
  await expect(removedRow).toHaveCount(1);
  const deleteOneRefreshStart = h4.connectionRouteRefreshAudit.length;
  await removedRow.locator(".key-trash").click();
  await page.locator(".key-delete-confirm .key-confirm-yes").click();
  const deleteOneRefresh = await expectConnectionRouteRefresh(
    h4,
    deleteOneRefreshStart,
    { manualConnections: 1, enabledManualConnections: 1, responseStatus: 200 },
  );
  await expect(page.locator("#settingsModelList .model-provider-label").filter({
    hasText: "DeepSeek",
  })).toHaveCount(0);
  await expect(page.locator("#settingsModelList .model-provider-label").filter({
    hasText: "workbar",
  })).toHaveCount(1);
  await page.locator("#closeSettingsPage").click();

  const afterDeleteOne = await page.evaluate(async ({ model, removedRouteRef }) => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const catalog = await response.json();
    const selectedRouteRef = localStorage.getItem("code-model-route-ref") || "";
    const routes = (catalog.routes || []).filter((route) => route.modelId === model);
    return {
      status: response.status,
      selectedRouteRef,
      selectedLabel: String(routes.find((route) => route.routeRef === selectedRouteRef)?.label || ""),
      routeLabels: routes.map((route) => route.label),
      removedStillPresent: routes.some((route) => route.routeRef === removedRouteRef),
    };
  }, { model: CONNECTION_SHARED_MODEL_ID, removedRouteRef: removedRoute.routeRef });
  expect(afterDeleteOne).toEqual({
    status: 200,
    selectedRouteRef: expect.stringMatching(/^mr1_[a-f0-9]{64}$/),
    selectedLabel: "workbar",
    routeLabels: ["workbar"],
    removedStillPresent: false,
  });

  const survivingRequest = page.waitForRequest((request) => {
    const url = new URL(request.url());
    return request.method() === "POST" && url.pathname === "/api/agent/runs";
  });
  await h4.submit(CONNECTION_ROUTE_USER);
  const survivingBody = (await survivingRequest).postDataJSON();
  expect(survivingBody.routeRef).toBe(afterDeleteOne.selectedRouteRef);
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: CONNECTION_ROUTE_FINAL,
  })).toHaveCount(1);
  expect(h4.controlIds().agentRunIds).toHaveLength(initialAgentRuns + 1);
  expect((await h4.metrics()).chatRequests).toHaveLength(1);

  await page.route("**/api/model-routes/refresh", async (route) => {
    await route.fulfill({
      status: 503,
      contentType: "application/json",
      body: JSON.stringify({
        error: "Model route catalog unavailable.",
        errorCode: "route_catalog_unavailable",
        retryable: true,
        routingV2: true,
        routes: [],
      }),
    });
  }, { times: 1 });
  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).toBeVisible();
  const finalRow = page.locator(
    '#settingsKeyList .key-row[data-connection-id="manual_h4_workbar_connection"]',
  );
  await expect(finalRow).toHaveCount(1);
  const visibleToggle = finalRow.locator(".key-enable");
  const hiddenToggleInput = visibleToggle.locator("input");
  await expect(visibleToggle).toBeVisible();
  await expect(hiddenToggleInput).toBeChecked();
  await expect(finalRow).not.toHaveClass(/disabled/);
  const failedDisableRefreshStart = h4.connectionRouteRefreshAudit.length;
  await visibleToggle.click();
  await expect(hiddenToggleInput).not.toBeChecked();
  await expect(finalRow).toHaveClass(/disabled/);
  await expect(visibleToggle).toHaveAttribute("title", "Disabled");
  await expect.poll(() => h4.connectionRouteRefreshAudit
    .slice(failedDisableRefreshStart)
    .find((record) => record.manualConnections === 0)?.responseStatus || 0).toBe(503);
  await expect.poll(() => h4.connectionRouteRefreshAudit
    .slice(failedDisableRefreshStart)
    .find((record) => record.manualConnections === 0)?.errorCode || "")
    .toBe("route_catalog_unavailable");
  const failedDisableRefresh = h4.connectionRouteRefreshAudit
    .slice(failedDisableRefreshStart)
    .find((record) => record.manualConnections === 0);
  expect(failedDisableRefresh?.errorCode).toBe("route_catalog_unavailable");
  await expect(page.locator("#settingsModelList .model-provider-group")).toHaveCount(0);
  await page.locator("#closeSettingsPage").click();
  await expect(page.locator("#modelPillBtn")).not.toHaveAttribute(
    "data-model",
    CONNECTION_SHARED_MODEL_ID,
  );
  expect(await page.evaluate(() => localStorage.getItem("code-model-route-ref"))).toBeNull();

  const beforeFailClosedAgentRuns = h4.controlIds().agentRunIds.length;
  const beforeFailClosedMetrics = await h4.metrics();
  await page.locator("#prompt").fill("H4_KEY_ROUTE_REVOKED");
  await expect(page.locator("#sendBtn")).toBeDisabled();
  await expect(page.locator("#activeRunBanner.visible")).toHaveCount(0);
  expect(h4.controlIds().agentRunIds).toHaveLength(beforeFailClosedAgentRuns);
  expect((await h4.metrics()).chatRequests).toEqual(beforeFailClosedMetrics.chatRequests);

  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).toBeVisible();
  const successfulDisableRefreshStart = h4.connectionRouteRefreshAudit.length;
  await page.locator("#settingsRefreshModels").click();
  const successfulDisableRefresh = await expectConnectionRouteRefresh(
    h4,
    successfulDisableRefreshStart,
    { manualConnections: 0, enabledManualConnections: 0, responseStatus: 200 },
  );
  const deleteLastRefreshStart = h4.connectionRouteRefreshAudit.length;
  await finalRow.locator(".key-trash").click();
  await page.locator(".key-delete-confirm .key-confirm-yes").click();
  await expect.poll(() => page.evaluate(() => (
    JSON.parse(localStorage.getItem("code-key-config") || "[]").length
  ))).toBe(0);
  expect(h4.connectionRouteRefreshAudit).toHaveLength(deleteLastRefreshStart);
  const disabledDeleteRefreshDelta =
    h4.connectionRouteRefreshAudit.length - deleteLastRefreshStart;
  await page.locator("#closeSettingsPage").click();

  const emptyCatalog = await page.evaluate(async () => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const body = await response.json();
    return {
      status: response.status,
      routes: body.routes || [],
      config: JSON.parse(localStorage.getItem("code-key-config") || "[]"),
      selectedRouteRef: localStorage.getItem("code-model-route-ref"),
    };
  });
  expect(emptyCatalog).toEqual({ status: 200, routes: [], config: [], selectedRouteRef: null });

  await page.context().route("**/api/code/sync-keys", async (route) => {
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify({ tokens: [], keys: {} }),
    });
  });
  await page.context().addInitScript(() => {
    sessionStorage.setItem("h4-preserve-key-config", "1");
    localStorage.setItem("code-key-config", "[]");
    localStorage.removeItem("code-model");
    localStorage.removeItem("code-model-route-ref");
    localStorage.removeItem("code-model-route-revision");
  });

  await page.reload({ waitUntil: "domcontentloaded" });
  await assertFrontendRuntime(page, runtime);
  await expect(page.locator("#modelPillDropdown .model-pill-optgroup")).toHaveCount(0);
  const afterReload = await page.evaluate(async () => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const body = await response.json();
    return { status: response.status, routes: body.routes || [] };
  });
  expect(afterReload).toEqual({ status: 200, routes: [] });

  await page.close();
  const transition = await h4.restartGeneration();
  expect(transition.currentPid).not.toBe(transition.previousPid);
  expect(transition.previousCleanup.childExited).toBe(true);
  expect(transition.previousCleanup.portsClosed).toEqual([true, true]);
  await h4.replacePage();
  const restartedTarget = runtime === "classic"
    ? `${h4.host.ready.codeUrl}/dist/frontend/index.classic.html`
    : `${h4.host.ready.codeUrl}/`;
  await h4.page.goto(restartedTarget, { waitUntil: "domcontentloaded" });
  await assertFrontendRuntime(h4.page, runtime);
  const afterRestart = await h4.page.evaluate(async () => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const body = await response.json();
    return {
      status: response.status,
      routes: body.routes || [],
      selectedRouteRef: localStorage.getItem("code-model-route-ref"),
    };
  });
  expect(afterRestart).toEqual({ status: 200, routes: [], selectedRouteRef: null });
  const restartMetrics = await h4.metrics();
  expect(restartMetrics.chatRequests).toEqual([]);
  expect(restartMetrics.production.agentRuns).toEqual([]);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-key-route-revocation`, {
    runtime,
    deleteOnePreservedOverlappingRoute: afterDeleteOne.selectedLabel,
    disableFailureStayedFailClosed: true,
    deleteLastClearedCatalog: emptyCatalog.routes.length === 0,
    reloadRoutes: afterReload.routes.length,
    restartRoutes: afterRestart.routes.length,
    refreshes: [deleteOneRefresh, failedDisableRefresh, successfulDisableRefresh]
      .map((record) => ({
        manualConnections: record?.manualConnections,
        responseStatus: record?.responseStatus,
        errorCode: record?.errorCode,
      })),
    disabledDeleteRefreshDelta,
  });
}

async function exerciseTrustedModelRoutePersistence(h4, runtime) {
  const { page } = h4;
  await h4.open(runtime);
  await assertFrontendRuntime(page, runtime);
  await page.evaluate(({ primaryKey, secondaryKey }) => {
    sessionStorage.setItem("h4-preserve-key-config", "1");
    localStorage.setItem("code-key-config", JSON.stringify([
      { name: "H4 primary group", key: primaryKey, enabled: true, source: "manual" },
      { name: "H4 trusted route group", key: secondaryKey, enabled: true, source: "manual" },
    ]));
  }, {
    primaryKey: h4.host.syntheticKey,
    secondaryKey: TRUSTED_ROUTE_SECONDARY_KEY,
  });

  await page.locator("#settingsMenuBtn").click();
  await expect(page.locator("#settingsPage")).toBeVisible();
  const refreshButton = page.locator("#settingsRefreshModels");
  await expect(refreshButton).toBeEnabled();
  await refreshButton.click();
  await expect(page.locator("#settingsModelList")).toContainText(TRUSTED_ROUTE_MODEL_ID);
  await expect(refreshButton).toBeEnabled();
  await page.locator("#closeSettingsPage").click();
  await page.locator("#modelPillBtn").click();
  await page.locator(`#modelPillDropdown [data-model="${TRUSTED_ROUTE_MODEL_ID}"]`).click();
  await expect(page.locator("#modelPillBtn")).toHaveAttribute(
    "data-model",
    TRUSTED_ROUTE_MODEL_ID,
  );

  const trustedCatalog = await page.evaluate(async ({ primaryKey, secondaryKey, model }) => {
    const response = await fetch("/api/model-routes", { cache: "no-store" });
    const catalog = await response.json();
    const serialized = JSON.stringify(catalog);
    const selectedRouteRef = localStorage.getItem("code-model-route-ref") || "";
    const selected = (catalog.routes || []).find((route) => route.routeRef === selectedRouteRef);
    return {
      status: response.status,
      version: Number(catalog.version || 0),
      routingV2: catalog.routingV2 === true,
      catalogRevision: Number(catalog.catalogRevision || 0),
      routeCount: Array.isArray(catalog.routes) ? catalog.routes.length : 0,
      selectedModel: String(selected?.modelId || ""),
      selectedConnectionLabel: String(selected?.label || ""),
      selectedRouteRefOpaque: /^mr1_[a-f0-9]{64}$/.test(selectedRouteRef),
      routeFields: Object.keys(selected || {}).sort(),
      containsSyntheticKey: serialized.includes(primaryKey) || serialized.includes(secondaryKey),
      containsGroupOrBaseUrl: Object.prototype.hasOwnProperty.call(selected || {}, "group")
        || Object.prototype.hasOwnProperty.call(selected || {}, "baseUrl"),
    };
  }, {
    primaryKey: h4.host.syntheticKey,
    secondaryKey: TRUSTED_ROUTE_SECONDARY_KEY,
    model: TRUSTED_ROUTE_MODEL_ID,
  });
  expect(trustedCatalog.catalogRevision).toBeGreaterThan(0);
  expect({
    ...trustedCatalog,
    catalogRevision: 1,
  }).toEqual({
    status: 200,
    version: 1,
    routingV2: true,
    catalogRevision: 1,
    routeCount: 2,
    selectedModel: TRUSTED_ROUTE_MODEL_ID,
    selectedConnectionLabel: "H4 trusted route group",
    selectedRouteRefOpaque: true,
    routeFields: [
      "connectionId", "credentialsAvailable", "enabled", "label",
      "modelId", "routeRef", "source",
    ],
    containsSyntheticKey: false,
    containsGroupOrBaseUrl: false,
  });

  await pinH4BaseUrlAcrossReloads(page, h4.host.ready.fakeUrl);
  const outage = await h4.host.command(
    "set-model-route-catalog-outage",
    { enabled: true },
  );
  expect(outage).toMatchObject({ ok: true, modelRoute: { catalogOutage: true } });
  await h4.reloadRuntime(runtime);
  await expect(page.locator("#baseUrl")).toHaveValue(h4.host.ready.fakeUrl);
  await expect(page.locator("#modelPillBtn")).toHaveAttribute(
    "data-model",
    TRUSTED_ROUTE_MODEL_ID,
  );
  await verifyTrustedRouteSettingsReady(page);
  const reloadIsolation = await page.evaluate(async (facts) => {
    const keyConfigRaw = localStorage.getItem("code-key-config") || "[]";
    let keyConfig = [];
    try { keyConfig = JSON.parse(keyConfigRaw); } catch {}
    const enabledKeys = (Array.isArray(keyConfig) ? keyConfig : [])
      .filter((entry) => entry?.enabled !== false)
      .map((entry) => String(entry?.key || ""))
      .sort();
    const expectedKeys = [facts.primaryKey, facts.secondaryKey].sort();
    const catalog = await (await fetch("/api/model-routes", { cache: "no-store" })).json();
    const routeRef = localStorage.getItem("code-model-route-ref") || "";
    const route = (catalog.routes || []).find((entry) => entry?.routeRef === routeRef);
    return {
      baseUrlMatchesFake: document.querySelector("#baseUrl")?.value === facts.fakeUrl,
      keysExactSyntheticPair: JSON.stringify(enabledKeys) === JSON.stringify(expectedKeys),
      routeRefStable: /^mr1_[a-f0-9]{64}$/.test(routeRef),
      routeModelMatches: String(route?.modelId || "") === facts.model,
      routeConnectionMatches: String(route?.label || "") === "H4 trusted route group",
      catalogContainsCredential: JSON.stringify(catalog).includes(facts.primaryKey)
        || JSON.stringify(catalog).includes(facts.secondaryKey),
    };
  }, {
    fakeUrl: h4.host.ready.fakeUrl,
    primaryKey: h4.host.syntheticKey,
    secondaryKey: TRUSTED_ROUTE_SECONDARY_KEY,
    model: TRUSTED_ROUTE_MODEL_ID,
  });
  expect(reloadIsolation).toEqual({
    baseUrlMatchesFake: true,
    keysExactSyntheticPair: true,
    routeRefStable: true,
    routeModelMatches: true,
    routeConnectionMatches: true,
    catalogContainsCredential: false,
  });

  const trustedSessionPutBoundary = h4.sessionPutBoundary();
  const trustedRunRequest = page.waitForRequest((request) => {
    const url = new URL(request.url());
    return request.method() === "POST" && url.pathname === "/api/agent/runs";
  });
  await h4.submit(TRUSTED_ROUTE_USER);
  const trustedRequestBody = (await trustedRunRequest).postDataJSON();
  expect(trustedRequestBody).toMatchObject({
    payload: { model: TRUSTED_ROUTE_MODEL_ID },
    routeRef: expect.stringMatching(/^mr1_[a-f0-9]{64}$/),
    catalogRevision: trustedCatalog.catalogRevision,
  });
  expect(Object.prototype.hasOwnProperty.call(trustedRequestBody, "keys")).toBe(false);
  expect(Object.prototype.hasOwnProperty.call(trustedRequestBody, "baseUrl")).toBe(false);
  expect(Object.prototype.hasOwnProperty.call(trustedRequestBody, "model")).toBe(false);
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: TRUSTED_ROUTE_FINAL,
  })).toHaveCount(1);
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(1);
  const trustedMetrics = await h4.metrics();
  expect(trustedMetrics.chatRequests).toHaveLength(1);
  expect(trustedMetrics.chatRequests[0]).toMatchObject({
    scenario: "trusted-model-route",
    trustedRoute: {
      keyGroup: "trusted-route",
      modelMatches: true,
      authorized: true,
    },
  });
  expect(trustedMetrics.production.agentRuns).toHaveLength(1);
  expect(trustedMetrics.production.agentRuns[0].status).toBe("completed");
  await expect.poll(() => {
    const firstMessageWrite = h4.sessionPutTimelineSince(trustedSessionPutBoundary)
      .find((entry) => entry.hasMessages);
    return firstMessageWrite ? {
      expectedRevision: firstMessageWrite.expectedRevision,
      pendingStatus: firstMessageWrite.pendingStatus,
      dispatchErrors: firstMessageWrite.dispatchErrors,
      finalAnswers: firstMessageWrite.finalAnswers,
      responseStatus: firstMessageWrite.responseStatus,
    } : null;
  }).toEqual({
    expectedRevision: 0,
    pendingStatus: "routing",
    dispatchErrors: 0,
    finalAnswers: 0,
    responseStatus: 200,
  });
  const trustedFirstSessionPut = h4.sessionPutTimelineSince(trustedSessionPutBoundary)
    .find((entry) => entry.hasMessages);

  await page.evaluate((trustedModel) => {
    localStorage.setItem("code-model", trustedModel);
    localStorage.setItem("code-model-catalog-cache-v1", JSON.stringify({
      version: 2,
      baseUrl: document.querySelector("#baseUrl")?.value || "",
      models: [trustedModel],
      entries: [{ id: trustedModel }],
      savedAt: Date.now(),
    }));
  }, TRUSTED_ROUTE_MODEL_ID);
  await h4.reloadRuntime(runtime);
  await expect(page.locator("#baseUrl")).toHaveValue(h4.host.ready.fakeUrl);
  await expect(page.locator("#modelPillBtn")).toHaveAttribute(
    "data-model",
    TRUSTED_ROUTE_MODEL_ID,
  );
  await verifyTrustedRouteSettingsReady(page);
  const settledSessionButton = page.locator("#sessionList .session-row.active button.session-main");
  await expect(settledSessionButton).toHaveCount(1);
  const settledSessionId = await settledSessionButton.getAttribute("data-session-id");
  expect(settledSessionId).toBeTruthy();
  await expect.poll(async () => {
    const response = await fetchProductionJson(
      page,
      `/api/sessions/${encodeURIComponent(settledSessionId)}`,
    );
    const successfulUser = response.body.messages.find((message) => (
      message?.role === "user" && String(message?.content || "") === TRUSTED_ROUTE_USER
    ));
    return {
      status: response.status,
      pendingStatus: String(successfulUser?.meta?.pendingDispatch?.status || ""),
      dispatchErrors: response.body.messages.filter((message) => (
        message?.meta?.kind === "dispatch-error"
      )).length,
      finalAnswers: response.body.messages.filter((message) => (
        message?.role === "assistant"
        && String(message?.content || "").includes(TRUSTED_ROUTE_FINAL)
      )).length,
    };
  }).toEqual({status: 200, pendingStatus: "", dispatchErrors: 0, finalAnswers: 1});
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: TRUSTED_ROUTE_FINAL,
  })).toHaveCount(1);
  const successfulSession = await fetchProductionJson(
    page,
    `/api/sessions/${encodeURIComponent(settledSessionId)}`,
  );
  const successfulRevision = Number(successfulSession.body.revision || 0);
  expect(successfulRevision).toBeGreaterThan(0);
  const unknownPreSubmitUi = await page.evaluate(() => ({
    stopDisabled: Boolean(document.querySelector("#stopBtn")?.disabled),
    activeBannerVisible: Boolean(document.querySelector("#activeRunBanner")?.classList.contains("visible")),
    userMessages: document.querySelectorAll("#messages article.msg.user").length,
    assistantMessages: document.querySelectorAll("#messages article.msg.assistant").length,
  }));
  const unknownPreSubmitClassification = {
    ui: unknownPreSubmitUi,
    runStateStatus: String(successfulSession.body?.runState?.status || ""),
    runStateAgentRunIdHash: successfulSession.body?.runState?.agentRunId
      ? idHash(successfulSession.body.runState.agentRunId)
      : "",
    observedAgentRunCount: h4.controlIds().agentRunIds.length,
  };
  expect(unknownPreSubmitClassification).toMatchObject({
    ui: {stopDisabled: true, activeBannerVisible: false},
    runStateStatus: "",
    runStateAgentRunIdHash: "",
    observedAgentRunCount: 1,
  });
  const routeRequestCountBeforeUnknown = (await h4.metrics()).modelRouteRequests.length;
  const agentRunCountBeforeUnknown = h4.controlIds().agentRunIds.length;
  const unknownDispatchBoundary = h4.requestBoundary();
  await h4.armModelCatalogGate();
  const immediateFeedbackStartedAt = Date.now();
  await page.locator("#prompt").fill("H4_UNKNOWN_MODEL_ROUTE_USER");
  await page.locator("#sendBtn").click();
  const unknownImmediateUi = await page.evaluate(() => ({
    stopDisabled: Boolean(document.querySelector("#stopBtn")?.disabled),
    activeBannerVisible: Boolean(document.querySelector("#activeRunBanner")?.classList.contains("visible")),
    unknownUserMessages: [...document.querySelectorAll("#messages article.msg.user")]
      .filter((element) => String(element.textContent || "").includes("H4_UNKNOWN_MODEL_ROUTE_USER"))
      .length,
  }));
  h4.diagnosticSteps.push({
    step: "unknown-submit-classification",
    runtime,
    before: unknownPreSubmitClassification,
    immediate: unknownImmediateUi,
  });
  const pendingUser = page.locator("#messages article.msg.user").filter({
    hasText: "H4_UNKNOWN_MODEL_ROUTE_USER",
  });
  await expect(pendingUser).toHaveCount(1, { timeout: 500 });
  const immediateFeedbackMs = Date.now() - immediateFeedbackStartedAt;
  expect(immediateFeedbackMs).toBeLessThan(500);
  await expect(page.locator("#activeRunBanner.visible .active-run-line[role='status']"))
    .toBeVisible();
  const catalogGate = await h4.waitModelCatalogGate();
  expect(catalogGate).toMatchObject({ armed: true, reached: true, released: false });
  expect(h4.controlIds().agentRunIds).toHaveLength(agentRunCountBeforeUnknown);
  expect(
    h4.requestSummarySince(unknownDispatchBoundary)["POST /api/agent/runs"] || 0,
  ).toBe(0);
  const activeSessionButton = page.locator("#sessionList .session-row.active button.session-main");
  await expect(activeSessionButton).toHaveCount(1);
  const pendingSessionId = await activeSessionButton.getAttribute("data-session-id");
  expect(pendingSessionId).toBeTruthy();
  const pendingSession = await fetchProductionJson(
    page,
    `/api/sessions/${encodeURIComponent(pendingSessionId)}`,
  );
  expect(pendingSession.status).toBe(200);
  const pendingDispatchUser = pendingSession.body.messages.find((message) => (
    message?.role === "user"
    && String(message?.content || "") === "H4_UNKNOWN_MODEL_ROUTE_USER"
  ));
  expect(pendingDispatchUser?.meta?.pendingDispatch?.status).toBe("routing");
  await h4.releaseModelCatalogGate();
  await expect.poll(async () => (
    (await h4.metrics()).modelRouteRequests.length - routeRequestCountBeforeUnknown
  )).toBe(2);
  await expect(pendingUser).toHaveCount(1);
  await expect(page.locator("#activeRunBanner.visible")).toHaveCount(0);
  expect(h4.controlIds().agentRunIds).toHaveLength(agentRunCountBeforeUnknown);
  expect(
    h4.requestSummarySince(unknownDispatchBoundary)["POST /api/agent/runs"] || 0,
  ).toBe(0);
  const failedMetrics = await h4.metrics();
  const unknownRefreshRequests = failedMetrics.modelRouteRequests.slice(
    routeRequestCountBeforeUnknown,
  );
  expect(unknownRefreshRequests).toEqual([
    { kind: "catalog", keyGroup: "primary", catalogOutage: true },
    { kind: "catalog", keyGroup: "trusted-route", catalogOutage: true },
  ]);
  const failedSession = await fetchProductionJson(
    page,
    `/api/sessions/${encodeURIComponent(pendingSessionId)}`,
  );
  const failedDispatchUser = failedSession.body.messages.find((message) => (
    message?.role === "user"
    && String(message?.content || "") === "H4_UNKNOWN_MODEL_ROUTE_USER"
  ));
  expect(failedDispatchUser?.meta?.pendingDispatch).toMatchObject({
    status: "failed",
    attempt: 1,
  });
  expect(failedSession.body.messages.filter((message) => (
    message?.meta?.kind === "dispatch-error"
  ))).toHaveLength(1);
  const failedRevision = Number(failedSession.body.revision || 0);
  expect(failedRevision).toBeGreaterThan(successfulRevision);

  const restoredRoute = await h4.host.command(
    "set-model-route-catalog-outage",
    { enabled: false },
  );
  expect(restoredRoute).toMatchObject({ ok: true, modelRoute: { catalogOutage: false } });
  await h4.reloadRuntime(runtime);
  await expect(page.locator("#messages article.msg.user").filter({
    hasText: "H4_UNKNOWN_MODEL_ROUTE_USER",
  })).toHaveCount(1);
  expect(h4.controlIds().agentRunIds).toHaveLength(agentRunCountBeforeUnknown);
  await expect(page.locator("#modelPillBtn")).toHaveAttribute(
    "data-model",
    TRUSTED_ROUTE_MODEL_ID,
  );

  await h4.submit("H4_UNKNOWN_MODEL_ROUTE_USER");
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: TRUSTED_ROUTE_FINAL,
  })).toHaveCount(2);
  await expect(page.locator("#messages article.msg.user").filter({
    hasText: "H4_UNKNOWN_MODEL_ROUTE_USER",
  })).toHaveCount(1);
  await expect.poll(() => h4.controlIds().agentRunIds.length)
    .toBe(agentRunCountBeforeUnknown + 1);
  const terminalMetrics = await h4.metrics();
  expect(terminalMetrics.chatRequests).toHaveLength(2);
  expect(terminalMetrics.production.agentRuns).toHaveLength(2);
  expect(terminalMetrics.production.agentRuns.every((run) => run.status === "completed"))
    .toBe(true);
  expect(
    h4.requestSummarySince(unknownDispatchBoundary)["POST /api/agent/runs"] || 0,
  ).toBe(1);
  const retriedSession = await fetchProductionJson(
    page,
    `/api/sessions/${encodeURIComponent(pendingSessionId)}`,
  );
  expect(retriedSession.body.messages.filter((message) => (
    message?.role === "user"
    && String(message?.content || "") === "H4_UNKNOWN_MODEL_ROUTE_USER"
  ))).toHaveLength(1);
  expect(retriedSession.body.messages.some((message) => (
    message?.meta?.kind === "dispatch-error"
  ))).toBe(false);
  const retriedRevision = Number(retriedSession.body.revision || 0);
  expect(retriedRevision).toBeGreaterThan(failedRevision);
  expect(terminalMetrics.toolExecutions).toEqual([]);
  expect(terminalMetrics.unsafeToolRequests).toBe(0);
  expectAutoPermissionNetworkIsolation(h4);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-trusted-model-route`, {
    runtime,
    routeCatalogVersion: trustedCatalog.version,
    routeCatalogRevision: trustedCatalog.catalogRevision,
    routeCatalogContainsCredential: trustedCatalog.containsSyntheticKey,
    reloadIsolation,
    reloadUsedTrustedRoute: true,
    trustedChatKeyGroup: trustedMetrics.chatRequests[0].trustedRoute.keyGroup,
    unknownRefreshKeyGroups: unknownRefreshRequests.map((request) => request.keyGroup),
    unknownDispatchBlockedBeforeAgentRun: true,
    successfulReloadNoDispatchError: true,
    immediateFeedbackMs,
    pendingPersistedBeforeRoute: pendingDispatchUser?.meta?.pendingDispatch?.status === "routing",
    retryReusedOneMessage: true,
    retryCreatedExactlyOneAgentRun: true,
    unknownSubmitClassification: {
      before: unknownPreSubmitClassification,
      immediate: unknownImmediateUi,
      persistedPendingStatus: pendingDispatchUser?.meta?.pendingDispatch?.status || "",
    },
    sessionRevisionAdvanced: successfulRevision < failedRevision
      && failedRevision < retriedRevision,
    firstSessionPut: trustedFirstSessionPut,
    sessionPutTimeline: h4.sessionPutTimelineSince(trustedSessionPutBoundary),
  });
}

async function exerciseHistoricToolMessageProtocol(h4, runtime) {
  const seededResponse = await h4.host.command("seed-tool-protocol-history");
  expect(seededResponse).toMatchObject({
    ok: true,
    toolProtocolHistory: { toolCallId: "h4-history-tool-call" },
  });
  const seeded = seededResponse.toolProtocolHistory;
  const { page } = h4;
  await h4.open(runtime);
  await assertFrontendRuntime(page, runtime);
  const sessionButton = page.locator(
    `#sessionList button.session-main[data-session-id="${seeded.sessionId}"]`,
  );
  await expect(sessionButton).toHaveCount(1);
  await sessionButton.click();
  await expect(page.locator(
    `#sessionList .session-row.active button.session-main[data-session-id="${seeded.sessionId}"]`,
  )).toHaveCount(1);
  await expect(page.locator("#messages article.msg.user").filter({
    hasText: "H4_TOOL_PROTOCOL_STEER",
  })).toHaveCount(1);

  await h4.submit(TOOL_PROTOCOL_CONTINUE_USER);
  await expect(page.locator("#messages article.msg.assistant").filter({
    hasText: TOOL_PROTOCOL_FINAL,
  })).toHaveCount(1);
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(1);
  const metrics = await h4.metrics();
  expect(metrics.chatRequests).toHaveLength(1);
  expect(metrics.chatRequests[0]).toMatchObject({
    scenario: "tool-protocol-history",
    toolProtocol: {
      assistantCallCount: 1,
      toolResultCount: 1,
      steerCount: 1,
      pairedOrder: true,
      orphanToolCount: 0,
    },
  });
  expect(metrics.production.agentRuns).toHaveLength(1);
  expect(metrics.production.agentRuns[0].status).toBe("completed");
  expect(metrics.toolExecutions).toEqual([]);
  expect(metrics.unsafeToolRequests).toBe(0);
  expectAutoPermissionNetworkIsolation(h4);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-tool-message-protocol`, {
    runtime,
    sessionId: idHash(seeded.sessionId),
    assistantCallCount: metrics.chatRequests[0].toolProtocol.assistantCallCount,
    toolResultCount: metrics.chatRequests[0].toolProtocol.toolResultCount,
    steerPreserved: metrics.chatRequests[0].toolProtocol.steerCount === 1,
    orphanToolCount: metrics.chatRequests[0].toolProtocol.orphanToolCount,
  });
}

async function startSkillEvidenceGate(h4, runtime, userMarker) {
  await h4.open(runtime);
  await assertFrontendRuntime(h4.page, runtime);
  await h4.submit(`/code-review ${userMarker}`);

  const panel = h4.page.locator("#skillEvidencePanel");
  await expect(panel).toBeVisible({ timeout: 30_000 });
  await expect(panel).toContainText("Skill evidence needs confirmation");
  await expect(panel.locator("[data-skill-evidence-action]")).toHaveCount(3);
  await expect(panel.locator('[data-skill-evidence-action="continue"]'))
    .toHaveText("Continue validation");
  await expect(panel.locator('[data-skill-evidence-action="skip"]'))
    .toHaveText("Skip and finish");
  await expect(panel.locator('[data-skill-evidence-action="cancel"]'))
    .toHaveText("Cancel task");
  await expect.poll(() => h4.controlIds().agentRunIds.length).toBe(1);

  const runId = h4.controlIds().agentRunIds[0];
  const active = h4.page.locator(
    "#sessionList .session-row.active button.session-main",
  );
  await expect(active).toHaveCount(1);
  const sessionId = String(await active.getAttribute("data-session-id") || "");
  const snapshot = await fetchProductionJson(
    h4.page,
    `/api/agent/runs/${encodeURIComponent(runId)}?cursor=0&wait=0`,
  );
  expect(snapshot.status).toBe(200);
  expect(snapshot.body).toMatchObject({
    status: "waiting_skill_evidence",
    skillEvidence: { status: "partial" },
    pendingSkillEvidence: {
      evidenceStatus: "partial",
      activeSkill: { name: "code-review" },
    },
  });
  expect(JSON.stringify(snapshot.body.pendingSkillEvidence))
    .not.toContain(SKILL_EVIDENCE_CANDIDATE);
  const gateId = snapshot.body.pendingSkillEvidence.gateId;
  expect(String(gateId || "")).not.toBe("");
  const metrics = await h4.metrics();
  expect(metrics.chatRequests.filter((entry) => (
    entry.scenario === "skill-evidence-candidate"
  ))).toHaveLength(1);
  expect(metrics.toolExecutions).toEqual([]);
  return { gateId, runId, sessionId };
}

async function exerciseSkillEvidenceContinue(h4, runtime) {
  const gate = await startSkillEvidenceGate(
    h4,
    runtime,
    `${SKILL_EVIDENCE_USER}_CONTINUE`,
  );
  const beforeContinue = await h4.metrics();
  const continueActionBoundary = h4.requestBoundary();
  await h4.page.locator(
    '#skillEvidencePanel [data-skill-evidence-action="continue"]',
  ).click();
  await expect(h4.page.locator("#messages article.msg.assistant").filter({
    hasText: SKILL_EVIDENCE_FINAL,
  })).toHaveCount(1, { timeout: 30_000 });
  await expect(h4.page.locator("#skillEvidencePanel")).toBeHidden();

  const terminal = await fetchProductionJson(
    h4.page,
    `/api/agent/runs/${encodeURIComponent(gate.runId)}?cursor=0&wait=0`,
  );
  expect(terminal.body).toMatchObject({
    status: "completed",
    result: { content: SKILL_EVIDENCE_FINAL },
    skillEvidence: { status: "satisfied" },
    pendingSkillEvidence: null,
    skillEvidenceOverride: null,
  });
  const readExecutions = (terminal.body.toolExecutions || []).filter((entry) => (
    entry.name === "read_file"
  ));
  expect(readExecutions).toHaveLength(1);
  expect(readExecutions[0].status).toBe("completed");
  const afterContinue = await h4.metrics();
  expect(afterContinue.chatRequests.slice(beforeContinue.chatRequests.length).map((entry) => (
    entry.scenario
  ))).toEqual(["skill-evidence-call", "skill-evidence-final"]);
  expect(afterContinue.chatRequests.at(-1).skillEvidence).toEqual({
    originalUserCount: 1,
    continuationCount: 1,
    toolReceiptCount: 1,
  });
  expect(afterContinue.toolExecutions).toEqual([
    { action: "read_file", path: "fixture.txt" },
  ]);
  const continueActionRequests = h4.requestSummarySince(continueActionBoundary);
  expect(continueActionRequests["POST /api/agent/runs/[id]/skill-evidence"]).toBe(1);
  expect(continueActionRequests["POST /api/agent/runs/[id]/resume"]).toBe(1);
  const session = await fetchProductionJson(
    h4.page,
    `/api/sessions/${encodeURIComponent(gate.sessionId)}`,
  );
  expect((session.body.messages || []).filter((message) => (
    message.role === "user" && String(message.content || "").includes(SKILL_EVIDENCE_USER)
  ))).toHaveLength(1);

  const duplicateMetrics = await h4.metrics();
  const duplicate = await sendProductionJson(
    h4.page,
    `/api/agent/runs/${encodeURIComponent(gate.runId)}/skill-evidence`,
    "POST",
    {
      gateId: gate.gateId,
      action: "continue",
      actionId: `skill-evidence:${gate.gateId}:continue`,
    },
  );
  expect(duplicate.status).toBe(200);
  expect(await h4.metrics()).toEqual(duplicateMetrics);

  const reloadBoundary = h4.requestBoundary();
  await h4.reloadRuntime(runtime);
  const restoredSession = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"]`,
  );
  await expect(restoredSession).toHaveCount(1);
  await restoredSession.click();
  await expect(h4.page.locator("#messages article.msg.assistant").filter({
    hasText: SKILL_EVIDENCE_FINAL,
  })).toHaveCount(1);
  const afterReload = await h4.metrics();
  expect(afterReload.chatRequests).toEqual(afterContinue.chatRequests);
  expect(afterReload.toolExecutions).toEqual(afterContinue.toolExecutions);
  expect(afterReload.production.agentRuns).toEqual(afterContinue.production.agentRuns);
  expect(afterReload.productionToolDelegations)
    .toBe(afterContinue.productionToolDelegations);
  expect(afterReload.unsafeToolRequests).toBe(afterContinue.unsafeToolRequests);
  expect(afterReload.fakeRequests.slice(afterContinue.fakeRequests.length).every((entry) => (
    entry.kind === "platform-sync"
  ))).toBe(true);
  const reloadRequests = h4.requestEvidenceSince(reloadBoundary);
  expect(reloadRequests.agentPost).toBe(0);
  expect(reloadRequests.runtimePost).toBe(0);
  const reloadRequestSummary = h4.requestSummarySince(reloadBoundary);
  expect(reloadRequestSummary["POST /api/agent/runs/[id]/skill-evidence"] || 0).toBe(0);
  expect(reloadRequestSummary["POST /api/agent/runs/[id]/resume"] || 0).toBe(0);
  expectAutoPermissionNetworkIsolation(h4);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-skill-evidence-continue`, {
    runtime,
    runId: idHash(gate.runId),
    uniqueReadExecutionCount: readExecutions.length,
    originalUserCount: afterContinue.chatRequests.at(-1).skillEvidence.originalUserCount,
    continuationCount: afterContinue.chatRequests.at(-1).skillEvidence.continuationCount,
    duplicateModelDelta: 0,
  });
}

async function exerciseSkillEvidenceRestartAction(h4, runtime, action) {
  const marker = action === "skip" ? "RESTART_SKIP" : "RESTART_CANCEL";
  const gate = await startSkillEvidenceGate(
    h4,
    runtime,
    `${SKILL_EVIDENCE_USER}_${marker}`,
  );
  const inactiveResponse = await sendProductionJson(
    h4.page,
    "/api/sessions",
    "POST",
    { title: `H4 Skill evidence ${action} inactive ${runtime}` },
  );
  expect(inactiveResponse.status).toBe(201);
  const inactiveSessionId = inactiveResponse.body.id;

  await h4.reloadRuntime(runtime);
  let inactiveButton = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${inactiveSessionId}"]`,
  );
  let gateButton = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"]`,
  );
  await expect(inactiveButton).toHaveCount(1);
  await expect(gateButton).toHaveCount(1);
  await inactiveButton.click();
  await expect(h4.page.locator(
    `#sessionList .session-row.active[data-session-id="${inactiveSessionId}"]`,
  )).toHaveCount(1);
  await expect(h4.page.locator("#skillEvidencePanel")).toBeHidden();
  const statusSlot = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"] .session-status-slot`,
  );
  await expect(statusSlot).toHaveAttribute(
    "data-session-status",
    "waiting-skill-evidence",
  );
  await expect(statusSlot).toHaveAttribute("title", "Waiting for Skill evidence");
  await h4.reloadRuntime(runtime);
  gateButton = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"]`,
  );
  await expect(gateButton).toHaveCount(1);
  await gateButton.click();
  await expect(h4.page.locator(
    `#sessionList .session-row.active[data-session-id="${gate.sessionId}"]`,
  )).toHaveCount(1);
  await expect(h4.page.locator("#skillEvidencePanel")).toBeVisible({ timeout: 30_000 });

  const processAPid = h4.host.childPid;
  await h4.page.close();
  const restartBoundary = h4.requestBoundary();
  const transition = await h4.restartGeneration();
  expect(transition.previousPid).toBe(processAPid);
  expect(transition.currentPid).not.toBe(transition.previousPid);
  expect(transition.previousCleanup.childExited).toBe(true);
  expect(transition.previousCleanup.portsClosed).toEqual([true, true]);
  expect(transition.previousCleanup.rootRetained).toBe(true);
  await h4.replacePage();
  await h4.open(runtime);
  inactiveButton = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${inactiveSessionId}"]`,
  );
  gateButton = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"]`,
  );
  await expect(inactiveButton).toHaveCount(1);
  await expect(gateButton).toHaveCount(1);
  await inactiveButton.click();
  await expect(h4.page.locator("#skillEvidencePanel")).toBeHidden();
  const restoredStatusSlot = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"] .session-status-slot`,
  );
  await expect(restoredStatusSlot).toHaveAttribute(
    "data-session-status",
    "waiting-skill-evidence",
  );
  await h4.reloadRuntime(runtime);
  gateButton = h4.page.locator(
    `#sessionList button.session-main[data-session-id="${gate.sessionId}"]`,
  );
  await expect(gateButton).toHaveCount(1);
  await gateButton.click();
  await expect(h4.page.locator(
    `#sessionList .session-row.active[data-session-id="${gate.sessionId}"]`,
  )).toHaveCount(1);
  await expect(h4.page.locator("#skillEvidencePanel")).toBeVisible({ timeout: 30_000 });
  const restored = await fetchProductionJson(
    h4.page,
    `/api/agent/runs/${encodeURIComponent(gate.runId)}?cursor=0&wait=0`,
  );
  expect(restored.body).toMatchObject({
    status: "waiting_skill_evidence",
    pendingSkillEvidence: { gateId: gate.gateId },
  });
  expect(JSON.stringify(restored.body.pendingSkillEvidence))
    .not.toContain(SKILL_EVIDENCE_CANDIDATE);
  expect(h4.requestEvidenceSince(restartBoundary).agentPost).toBe(0);

  const beforeAction = await h4.metrics();
  const actionBoundary = h4.requestBoundary();
  await h4.page.locator(
    `#skillEvidencePanel [data-skill-evidence-action="${action}"]`,
  ).click();
  await expect(h4.page.locator("#skillEvidencePanel")).toBeHidden();
  await expect.poll(async () => (
    await fetchProductionJson(
      h4.page,
      `/api/agent/runs/${encodeURIComponent(gate.runId)}?cursor=0&wait=0`,
    )
  ).body.status).toBe(action === "skip" ? "completed" : "cancelled");
  const terminal = await fetchProductionJson(
    h4.page,
    `/api/agent/runs/${encodeURIComponent(gate.runId)}?cursor=0&wait=0`,
  );
  if (action === "skip") {
    await expect(h4.page.locator("#messages article.msg.assistant").filter({
      hasText: SKILL_EVIDENCE_CANDIDATE,
    })).toHaveCount(1);
    expect(terminal.body).toMatchObject({
      status: "completed",
      skillEvidence: { status: "unsupported_completion" },
      skillEvidenceOverride: {
        action: "skip",
        actionId: `skill-evidence:${gate.gateId}:skip`,
      },
    });
  } else {
    expect(terminal.body.result).toEqual({});
    expect((terminal.body.events || []).filter((event) => (
      event.type === "skill_evidence_action"
    ))).toHaveLength(1);
    expect((terminal.body.events || []).find((event) => (
      event.type === "skill_evidence_action"
    ))?.data).toMatchObject({
      action: "cancel",
      actionId: `skill-evidence:${gate.gateId}:cancel`,
    });
  }
  const actionRequests = h4.requestSummarySince(actionBoundary);
  expect(actionRequests["POST /api/agent/runs/[id]/skill-evidence"]).toBe(1);
  const afterAction = await h4.metrics();
  expect(afterAction.chatRequests).toEqual(beforeAction.chatRequests);
  expect(afterAction.toolExecutions).toEqual(beforeAction.toolExecutions);
  expect(afterAction.unsafeToolRequests).toBe(0);
  const sessionList = await fetchProductionJson(h4.page, "/api/sessions");
  const sessionSummary = (sessionList.body.data || []).find((item) => (
    item.id === gate.sessionId
  ));
  expect(sessionSummary?.interactionState).toBe("");
  const session = await fetchProductionJson(
    h4.page,
    `/api/sessions/${encodeURIComponent(gate.sessionId)}`,
  );
  expect((session.body.messages || []).filter((message) => (
    message.role === "user" && String(message.content || "").includes(SKILL_EVIDENCE_USER)
  ))).toHaveLength(1);

  const duplicateMetrics = await h4.metrics();
  const duplicate = await sendProductionJson(
    h4.page,
    `/api/agent/runs/${encodeURIComponent(gate.runId)}/skill-evidence`,
    "POST",
    {
      gateId: gate.gateId,
      action,
      actionId: `skill-evidence:${gate.gateId}:${action}`,
    },
  );
  expect(duplicate.status).toBe(200);
  expect(await h4.metrics()).toEqual(duplicateMetrics);
  expectAutoPermissionNetworkIsolation(h4);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-skill-evidence-restart-${action}`, {
    runtime,
    action,
    runId: idHash(gate.runId),
    restartPreservedGate: restored.body.pendingSkillEvidence.gateId === gate.gateId,
    nonCurrentStatus: "waiting-skill-evidence",
    modelDeltaAfterRestart: 0,
    toolDeltaAfterRestart: 0,
    uniqueUserCount: 1,
  });
}

