function boundedToolExecutionResult(execution) {
  const result = execution?.result;
  return {
    toolCallId: String(execution?.toolCallId || ""),
    status: String(execution?.status || ""),
    authorizationDecision: String(execution?.authorizationDecision || ""),
    resultIsObject: Boolean(result && typeof result === "object" && !Array.isArray(result)),
    ok: result?.ok === true,
    errorCode: String(result?.errorCode || ""),
    operation: String(result?.operation || ""),
    path: String(result?.path || ""),
    mimeType: String(result?.mimeType || ""),
    sha256Valid: /^[0-9a-f]{64}$/.test(String(result?.sha256 || "")),
    byteLength: Math.max(0, Number(result?.byteLength || 0)),
  };
}

async function waitForBoundAgentAuthorization(h4, {
  runId,
  toolCallId,
  action,
  previousAuthorizationId = "",
  expectedCount = null,
  expectedReference,
  expectedPath = "",
  expectedManageResult = null,
}) {
  let binding = null;
  await expect.poll(async () => {
    const snapshot = await fetchProductionJson(
      h4.page,
      `/api/agent/runs/${encodeURIComponent(runId)}?cursor=0&wait=0`,
    );
    const pending = snapshot.body?.pendingAuthorization || {};
    const execution = (snapshot.body?.toolExecutions || []).find(
      (entry) => entry.toolCallId === toolCallId,
    );
    const authorizationId = String(pending.authorizationId || "");
    if (execution?.status === "completed" && pending.toolCallId !== toolCallId) {
      const projection = boundedToolExecutionResult({ ...execution, toolCallId });
      h4.diagnosticSteps.push({
        step: "authorization-missing-after-terminal-tool-result",
        ...projection,
      });
      throw new Error(`H4 authorization was skipped after terminal tool result: ${JSON.stringify(projection)}`);
    }
    if (
      snapshot.status !== 200
      || snapshot.body?.status !== "waiting_authorization"
      || !authorizationId
      || authorizationId === previousAuthorizationId
      || pending.toolCallId !== toolCallId
      || pending.action !== action
      || !execution
    ) {
      return false;
    }
    binding = { authorizationId, execution, snapshot: snapshot.body };
    return true;
  }, { timeout: 30_000 }).toBe(true);

  const args = JSON.parse(binding.execution.arguments || "{}");
  if (expectedCount !== null) expect(args.count).toBe(expectedCount);
  if (expectedReference === null) expect(args).not.toHaveProperty("reference");
  if (expectedReference && typeof expectedReference === "object") {
    expect(args.reference).toEqual(expectedReference);
  }

  const panel = h4.page.locator("#authorizationPanel");
  await expect(panel).toBeVisible({ timeout: 30_000 });
  const row = panel.locator(
    `.authorization-row[data-auth-id="server-authorization-${binding.authorizationId}"]`,
  );
  await expect(row).toHaveCount(1);
  if (expectedCount !== null) {
    const text = await row.innerText();
    expect(text).toContain(IMAGE_MODEL_ID);
    expect(text).toMatch(new RegExp(`${expectedCount} (?:image|\\u5f20)`, "i"));
    expect(text).toContain("png");
    expect(text).toMatch(new RegExp(
      `(?:up to ${expectedCount} independent image requests|\\u6700\\u591a ${expectedCount} \\u6b21\\u72ec\\u7acb\\u56fe\\u7247\\u8bf7\\u6c42)`,
      "i",
    ));
    expect(text).not.toContain("small blue geometric icon");
    expect(text).not.toContain("Turn the supplied image");
    if (expectedReference) expect(text).toMatch(/reference edit|\u53c2\u8003\u56fe\u7f16\u8f91/i);
  }
  if (expectedPath) await expect(row).toContainText(expectedPath);

  const approve = panel.locator('[data-auth-action="approve"]');
  await expect(approve).toBeEnabled();
  await approve.click();

  let completed = null;
  await expect.poll(async () => {
    const snapshot = await fetchProductionJson(
      h4.page,
      `/api/agent/runs/${encodeURIComponent(runId)}?cursor=0&wait=0`,
    );
    const pendingId = String(snapshot.body?.pendingAuthorization?.authorizationId || "");
    const execution = (snapshot.body?.toolExecutions || []).find(
      (entry) => entry.toolCallId === toolCallId,
    );
    if (
      snapshot.status !== 200
      || pendingId === binding.authorizationId
      || execution?.status !== "completed"
      || execution?.authorizationDecision !== "approved"
    ) {
      return false;
    }
    completed = { execution, snapshot: snapshot.body };
    return true;
  }, { timeout: 30_000 }).toBe(true);
  await expect(row).toHaveCount(0);
  const projection = boundedToolExecutionResult({ ...completed.execution, toolCallId });
  h4.diagnosticSteps.push({ step: "authorized-tool-result", ...projection });
  expect(projection.resultIsObject).toBe(true);
  expect(projection.ok).toBe(true);
  if (expectedManageResult) {
    const result = completed.execution.result;
    const expectedAbsolutePath = path.resolve(
      h4.host.projectDir,
      ...expectedManageResult.path.split("/"),
    );
    const absolutePathMatches = path.resolve(String(result.absolutePath || ""))
      === expectedAbsolutePath;
    const absolutePathWithinProject = expectedAbsolutePath.startsWith(
      `${path.resolve(h4.host.projectDir)}${path.sep}`,
    );
    let fileBytes = null;
    try {
      fileBytes = await fs.readFile(expectedAbsolutePath);
    } catch {}
    const fileHash = fileBytes
      ? crypto.createHash("sha256").update(fileBytes).digest("hex")
      : "";
    const fileEvidence = {
      operationMatches: result.operation === expectedManageResult.operation,
      pathMatches: result.path === expectedManageResult.path,
      absolutePathMatches,
      absolutePathWithinProject,
      mimeValid: /^image\/(?:png|jpeg|webp)$/.test(String(result.mimeType || "")),
      sha256Valid: /^[0-9a-f]{64}$/.test(String(result.sha256 || "")),
      byteLengthValid: Number(result.byteLength || 0) > 0,
      fileExists: Boolean(fileBytes),
      fileHashMatches: Boolean(fileBytes) && fileHash === result.sha256,
      fileBytesMatch: Boolean(fileBytes) && fileBytes.length === Number(result.byteLength || 0),
    };
    h4.diagnosticSteps.push({
      step: "managed-image-file-result-verified",
      toolCallId,
      ...fileEvidence,
    });
    expect(Object.values(fileEvidence).every(Boolean)).toBe(true);
  }
  return {
    authorizationId: binding.authorizationId,
    arguments: args,
    execution: completed.execution,
    snapshot: completed.snapshot,
  };
}

async function generatedAssetResponse(page, assetUrl) {
  return page.evaluate(async (url) => {
    const response = await fetch(url, { cache: "no-store" });
    const bytes = new Uint8Array(await response.arrayBuffer());
    return {
      status: response.status,
      contentType: response.headers.get("content-type") || "",
      cacheControl: response.headers.get("cache-control") || "",
      byteLength: bytes.length,
      png: bytes.length >= 8
        && [...bytes.slice(0, 8)].join(",") === "137,80,78,71,13,10,26,10",
    };
  }, assetUrl);
}

async function staleSessionPutThenAssetGetSameConnection(
  pageUrl,
  sessionId,
  assetUrl,
) {
  const origin = new URL(pageUrl).origin;
  const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
  const send = (method, requestPath, body) => new Promise((resolve, reject) => {
    const payload = body === undefined
      ? null
      : Buffer.from(JSON.stringify(body), "utf8");
    let socket = null;
    const request = http.request(new URL(requestPath, origin), {
      method,
      agent,
      headers: payload
        ? {
          "Content-Type": "application/json",
          "Content-Length": String(payload.length),
        }
        : undefined,
    }, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => {
        const raw = Buffer.concat(chunks).toString("utf8");
        let responseBody = null;
        try { responseBody = JSON.parse(raw); } catch {}
        resolve({
          status: Number(response.statusCode || 0),
          body: responseBody,
          reusedSocket: request.reusedSocket === true,
          socket,
        });
      });
    });
    request.on("socket", (value) => { socket = value; });
    request.on("error", reject);
    request.end(payload || undefined);
  });

  try {
    const stalePut = await send(
      "PUT",
      `/api/sessions/${encodeURIComponent(sessionId)}`,
      {
        title: "H4 stale save must stay deleted",
        messages: [],
        expectedRevision: 0,
      },
    );
    const assetGet = await send("GET", assetUrl);
    return {
      stalePut: {
        status: stalePut.status,
        errorCode: String(stalePut.body?.errorCode || ""),
      },
      assetGet: {
        status: assetGet.status,
        errorCode: String(assetGet.body?.errorCode || ""),
      },
      sameSocket: Boolean(stalePut.socket && stalePut.socket === assetGet.socket),
      assetRequestReusedSocket: assetGet.reusedSocket,
    };
  } finally {
    agent.destroy();
  }
}

async function forceImageRouteStale(h4, selectedRoute, suffix) {
  const before = await fetchProductionJson(h4.page, "/api/image-routes");
  expect(before.status).toBe(200);
  expect(before.body.routes).toHaveLength(1);
  expect(before.body.routes[0].routeRef).toBe(selectedRoute.routeRef);
  const changed = await sendProductionJson(
    h4.page,
    "/api/image-routes/refresh",
    "POST",
    {
      connections: [{
        connectionId: selectedRoute.connectionId,
        name: `${IMAGE_CONNECTION_NAME} stale ${suffix}`,
        baseUrl: h4.host.ready.fakeUrl,
        key: "h4-image-synthetic-credential",
        models: [{ id: IMAGE_MODEL_ID }],
      }],
    },
  );
  expect(changed.status).toBe(200);
  expect(changed.body.routes).toHaveLength(1);
  expect(changed.body.routes[0].routeRef).toBe(selectedRoute.routeRef);
  expect(changed.body.catalogRevision).toBeGreaterThan(before.body.catalogRevision);
  return {
    beforeRevision: Number(before.body.catalogRevision || 0),
    staleRevision: Number(changed.body.catalogRevision || 0),
  };
}

async function exerciseImageRouteCreateRebind(h4, runtime) {
  await h4.open(runtime);
  await assertFrontendRuntime(h4.page, runtime);
  await restoreEditAuthorizationTestConfig(h4);
  const selectedRoute = await configureImageGenerationConnection(h4);
  const { page } = h4;

  const runCase = async (caseName) => {
    const revision = await forceImageRouteStale(h4, selectedRoute, caseName);
    const beforeMetrics = await h4.metrics();
    const beforeRunIds = [...h4.controlIds().agentRunIds];
    const boundary = h4.requestBoundary();
    const createAttempts = [];
    const captureCreate = (response) => {
      const request = response.request();
      if (
        request.method() !== "POST"
        || new URL(response.url()).pathname !== "/api/agent/runs"
      ) return;
      let body = {};
      try { body = JSON.parse(request.postData() || "{}"); } catch {}
      createAttempts.push({
        status: response.status(),
        clientRequestId: String(body.clientRequestId || ""),
        imageRouteRef: String(body.imageRouteRef || ""),
        imageCatalogRevision: Number(body.imageCatalogRevision || 0),
      });
    };
    page.on("response", captureCreate);
    await h4.submit(`/imagegen ${IMAGE_GENERATION_USER}`);
    await waitForImageAuthorization(h4, false);
    await expect(page.locator("#messages article.msg.assistant").filter({
      hasText: IMAGE_GENERATION_FINAL,
    })).toHaveCount(1, { timeout: 30_000 });
    page.off("response", captureCreate);

    await expect.poll(() => h4.controlIds().agentRunIds.length)
      .toBe(beforeRunIds.length + 1);
    const runId = h4.controlIds().agentRunIds.find((id) => !beforeRunIds.includes(id));
    const run = await fetchProductionJson(
      page,
      `/api/agent/runs/${encodeURIComponent(runId)}?cursor=0&wait=0`,
    );
    expect(run.status).toBe(200);
    expect(run.body).toMatchObject({
      status: "completed",
      imageRoute: {
        routeRef: selectedRoute.routeRef,
        modelId: IMAGE_MODEL_ID,
      },
    });
    expect(String(run.body.clientRequestId || "")).not.toBe("");
    expect((run.body.toolExecutions || []).filter((entry) => (
      entry.name === "generate_image" && entry.status === "completed"
    ))).toHaveLength(1);
    expect((run.body.events || []).filter((entry) => (
      entry.type === "authorization_required"
    ))).toHaveLength(1);

    expect(createAttempts).toEqual([
      {
        status: 409,
        clientRequestId: expect.any(String),
        imageRouteRef: selectedRoute.routeRef,
        imageCatalogRevision: revision.beforeRevision,
      },
      {
        status: 201,
        clientRequestId: expect.any(String),
        imageRouteRef: selectedRoute.routeRef,
        imageCatalogRevision: expect.any(Number),
      },
    ]);
    expect(createAttempts[0].clientRequestId).not.toBe("");
    expect(createAttempts[1].clientRequestId).toBe(createAttempts[0].clientRequestId);
    expect(createAttempts[1].imageCatalogRevision).toBeGreaterThan(revision.staleRevision);
    const requests = h4.requestEvidenceSince(boundary);
    const summary = h4.requestSummarySince(boundary);
    expect(requests.agentPost).toBe(2);
    expect(summary["POST /api/image-routes/refresh"]).toBe(1);
    const afterMetrics = await h4.metrics();
    expect(afterMetrics.imageRequests.length).toBe(beforeMetrics.imageRequests.length + 1);
    expect(afterMetrics.chatRequests.length).toBe(beforeMetrics.chatRequests.length + 2);
    const sessionId = String(await page.locator(
      "#sessionList .session-row.active button.session-main",
    ).getAttribute("data-session-id") || "");
    const session = await fetchProductionJson(
      page,
      `/api/sessions/${encodeURIComponent(sessionId)}`,
    );
    expect((session.body.messages || []).filter((message) => (
      message.role === "user"
      && JSON.stringify(message.content || "").includes(IMAGE_GENERATION_USER)
    ))).toHaveLength(1);
    return { sessionId, runId };
  };

  const newSession = await runCase("new-session");
  const existing = await sendProductionJson(
    page,
    "/api/sessions",
    "POST",
    { title: `H4 image rebind existing ${runtime}` },
  );
  expect(existing.status).toBe(201);
  const existingSessionId = String(existing.body.id || "");
  expect(existingSessionId).not.toBe("");
  await pinH4BaseUrlAcrossReloads(page, h4.host.ready.fakeUrl);
  await page.evaluate(() => {
    sessionStorage.setItem("h4-preserve-permission-profile", "1");
    sessionStorage.setItem("h4-preserve-key-config", "1");
  });
  await h4.reloadRuntime(runtime);
  const existingButton = page.locator(
    `#sessionList button.session-main[data-session-id="${existingSessionId}"]`,
  );
  await expect(existingButton).toHaveCount(1);
  await existingButton.click();
  await expect(page.locator(
    `#sessionList .session-row.active[data-session-id="${existingSessionId}"]`,
  )).toHaveCount(1);
  const existingSession = await runCase("existing-session");
  expect(existingSession.sessionId).toBe(existingSessionId);
  expect(existingSession.runId).not.toBe(newSession.runId);
  expect(h4.controlIds().agentRunIds).toHaveLength(2);
  expectAutoPermissionNetworkIsolation(h4);
  expect(h4.pageErrors).toEqual([]);
  h4.evidence(`${runtime}-image-route-create-rebind`, {
    runtime,
    newSessionId: idHash(newSession.sessionId),
    existingSessionId: idHash(existingSession.sessionId),
    agentRuns: h4.controlIds().agentRunIds.length,
    imageRequests: (await h4.metrics()).imageRequests.length,
  });
}

